770:       Math.max(
771:         DISTANCE_AUTO_ROUTE_KM_MIN,
772:         Math.round((targetKm + deltaKm) / DISTANCE_AUTO_ROUTE_KM_STEP) * DISTANCE_AUTO_ROUTE_KM_STEP,
773:       ),
