780:   function setInlinePhase(
781:     phase: "idle" | "direction" | "searching" | "found" | "failed",
782:     message?: string,
783:   ) {
784:     autoRouteStatus.className = "map-view__pick-auto-route-status";
785:     autoRouteStatus.dataset.phase = phase;
786:     if (phase === "idle") {
787:       autoRouteStatus.textContent = "";
788:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--idle");
789:       return;
790:     }
791:     if (phase === "direction") {
792:       autoRouteStatus.textContent =
793:         message ?? formatDistanceAutoRouteDirectionClickHint(targetKm);
794:       return;
795:     }
796:     if (phase === "searching") {
797:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--searching");
798:       autoRouteStatus.textContent =
799:         message ?? "목표 거리에 맞는 도로 경로를 찾는 중입니다…";
800:       return;
801:     }
802:     if (phase === "failed") {
803:       autoRouteStatus.classList.add("map-view__pick-auto-route-status--failed");
804:       autoRouteStatus.textContent = message ?? "경로를 찾지 못했습니다.";
805:       return;
806:     }
807:     autoRouteStatus.classList.add("map-view__pick-auto-route-status--found");
808:     autoRouteStatus.textContent = message ?? "경로를 찾았습니다.";
809:   }
