815:     if (getRouteTokenInsufficient?.()) {
816:       setInlinePhase("failed", ROUTE_TOKEN_INSUFFICIENT_HINT);
817:       return;
818:     }
819:     const parsed = Number.parseFloat(distanceNumber.value);
820:     const validated = validateDistanceAutoRouteTargetKm(parsed);
821:     if (!validated.ok) {
822:       setInlinePhase("failed", validated.message);
823:       return;
824:     }
825:     syncDistanceInputs(validated.km);
826:     previewCircleForTargetKm(validated.km);
827:     const result = onArmDirectionPick({
828:       start,
829:       profile: currentProfile,
830:       targetKm: validated.km,
831:     });
832:     if (!result.ok) {
833:       setInlinePhase("failed", result.message);
834:       return;
835:     }
836:     autoSessionActive = true;
837:     const rerouteReady = autoRouteStatus.dataset.phase === "found";
838:     setInlinePhase(
839:       "direction",
840:       rerouteReady || autoRouteStatusMessage === DISTANCE_AUTO_ROUTE_REROUTE_HINT
841:         ? DISTANCE_AUTO_ROUTE_REROUTE_HINT
842:         : formatDistanceAutoRouteDirectionClickHint(validated.km),
843:     );
844:     onDirectionPickArmed?.();
845:   }
