47: export function pickPickPopupAnchor(
48:   map: mapboxgl.Map,
49:   e: mapboxgl.MapMouseEvent | mapboxgl.MapLayerMouseEvent,
50: ): "top" | "bottom" | "left" | "right" {
51:   const canvas = map.getCanvas();
52:   const w = Math.max(1, canvas.clientWidth);
53:   const h = Math.max(1, canvas.clientHeight);
54:   const { x, y } = e.point;
55:   const m = Math.min(80, w * 0.14, h * 0.13);
56:   if (y < m) return "top";
57:   if (y > h - m) return "bottom";
58:   if (x < m) return "left";
59:   if (x > w - m) return "right";
60:   return "bottom";
61: }
